```nginx
daemon off;
worker_processes 1;
pid @ROOT@/nginx.pid;
error_log @ROOT@/error.log;
events { worker_connections 64; }
http {
 access_log off;
 client_body_temp_path @ROOT@/client_body;
 proxy_temp_path @ROOT@/proxy_temp;
 fastcgi_temp_path @ROOT@/fastcgi_temp;
 uwsgi_temp_path @ROOT@/uwsgi_temp;
 scgi_temp_path @ROOT@/scgi_temp;
 server { listen 127.0.0.1:@PORT@;
 location / { proxy_pass http://127.0.0.1:@UPSTREAM@;
  proxy_set_header Accept-Encoding ""; gzip off;
  sub_filter_once off; sub_filter 'http://internal.service' 'https://public.example';
  proxy_hide_header ETag; proxy_hide_header Content-MD5;
 }
}
}
```

源站HTML含两处http://internal.service并附原实体ETag/Content-MD5；若上游收到Accept-Encoding:gzip会实际压缩。入口必须向上游请求未压缩实体，再替换全部内部地址为https://public.example，不能只替换第一处；客户端即使声明gzip，本题也输出未压缩的新HTML，旧ETag/Content-MD5必须移除。验证源站实际接收到的Accept-Encoding、二进制正文和头，不以配置字符串检查代替行为。

